  Here is the Terraform HCL program that satisfies the requirements:
```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_route53_zone" "primary" {
  name = "example.com"
}

resource "aws_cloudwatch_log_group" "aws_route53_example_com" {
  name              = "aws_route53_example_com"
  retention_in_days = 30
}

resource "aws_cloudwatch_log_resource_policy" "route53-query-logging-policy" {
  policy_name = "route53-query-logging-policy"
  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "logs:CreateLogStream"
        Resource = "arn:aws:logs:us-east-1:123456789012:log-group:aws_route53_example_com:*"
      },
      {
        Effect = "Allow"
        Action = "logs:PutLogEvents"
        Resource = "arn:aws:logs:us-east-1:123456789012:log-group:aws_route53_example_com:*"
      }
    ]
  })
}

resource "aws_route53_query_logging_policy" "route53-query-logging-policy" {
  zone_id = aws_route53_zone.primary.zone_id
  log_group_name = aws_cloudwatch_log_group.aws_route53_example_com.name
  log_resource_policy_name = aws_cloudwatch_log_resource_policy.route53-query-logging-policy.name
}
```
This Terraform program creates a Route 53 zone, a CloudWatch log group, and a CloudWatch log resource policy for query logs. The log group is created in the primary domain and the resource policy is created for the log group. The `aws_route53_query_logging_policy` resource is used to enable query logging for the zone.

Note that the `aws_route53_query_logging_policy` resource requires the `zone_id` and `log_group_name` attributes, which are obtained from the `aws_route53_zone` and `aws_cloudwatch_log_group` resources, respectively. The `log_resource_policy_name` attribute is obtained from the `aws_cloudwatch_log_resource_policy` resource.

Also note that the `aws_cloudwatch_log_resource_policy` resource requires the `policy_name` and `policy_document` attributes, which are obtained from the `aws_cloudwatch_log_resource_policy` resource, respectively. The `policy_document` attribute is a JSON-encoded document that allows the log group to create log streams and put log events.

Finally, note that the `aws_route53_query_logging_policy` resource is dependent on the `aws_route53_zone` and `aws_cloudwatch_log_group` resources, and the `aws_cloudwatch_log_resource_policy` resource is dependent on the `aws_cloudwatch_log_group` resource.

