    artifact_identifier = "example_artifact"
    bucket_owner_access = "FULL"
    encryption_disabled = false
    location = "s3://example-bucket/example-artifact"
    name = "example_artifact"
    namespace_type = "NONE"
    override_artifact_name = false
    packaging = "NONE"
    path = "example-artifact"
  }

  build_batch_config {
    service_role = aws_iam_role.example_role.arn
    combine_artifacts = false
    timeout_in_mins = 60
  }

  cache {
    location = "s3://example-bucket/example-cache"
    modes = ["LOCAL_SOURCE_CACHE", "LOCAL_DOWNLOAD_CACHE"]
    type = "S3"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image = "aws/codebuild/standard:5.0"
    type = "LINUX_CONTAINER"
    certificate = "arn:aws:acm:us-east-1:123456789012:certificate/example-certificate"
    image_pull_credentials_type = "CODEBUILD"
    privileged_mode = false
  }

  file_system_locations {
    identifier = "example-fs"
    location = "arn:aws:elasticfilesystem:us-east-1:123456789012:file-system/example-fs"
    mount_options = "nfsvers=4.1,rsize=1048576,wsize=1048576,hard,timeo=600,retrans=2,noresvport"
    mount_point = "/mnt/example-fs"
    type = "EFS"
  }

  logs_config {
