    type = "CODEPIPELINE"
    bucket_owner_access = "FULL"
    encryption_disabled = false
    location = "s3://example-bucket/example-artifact"
    name = "example_artifact"
    namespace_type = "NONE"
    override_artifact_name = false
    packaging = "NONE"
    path = "example-artifact"
  }

  secondary_source_version {
    source_identifier = "example-source"
    source_version = "example-version"
  }

  secondary_sources {
    source_identifier = "example-source"
    type = "GITHUB"
    buildspec = "example-buildspec"
    git_clone_depth = 1
    insecure_ssl = false
    location = "https://github.com/example-org/example-repo.git"
    report_build_status = false
  }

