    type = "GITHUB"
    buildspec = "example-buildspec"
    git_clone_depth = 1
    insecure_ssl = false
    location = "https://github.com/example-org/example-repo.git"
    report_build_status = false
  }

  vpc_config {
    security_group_ids = ["sg-12345678"]
    subnets = ["subnet-12345678"]
    vpc_id = "vpc-12345678"
  }
}
