  zone_id = aws_route53_zone.primary.zone_id
  records = ["192.0.2.1"]
}

resource "aws_route53_record" "eu_endpoint" {
  name    = "eu-endpoint.example.com"
  type    = "A"
  zone_id = aws_route53_zone.primary.zone_id
  records = ["192.0.2.2"]
}

resource "aws_route53_resolver_endpoint" "us_resolver" {
  direction = "INBOUND"
  security_group_ids = [aws_security_group.us_resolver.id]
  ip_address {
    subnet_id = aws_subnet.us_subnet.id
    ip        = "192.0.2.1"
  }
}

resource "aws_route53_resolver_endpoint" "eu_resolver" {
  direction = "INBOUND"
  security_group_ids = [aws_security_group.eu_resolver.id]
  ip_address {
    subnet_id = aws_subnet.eu_subnet.id
    ip        = "192.0.2.2"
  }
}

resource "aws_route53_resolver_rule" "location_based_routing" {
  domain_name = aws_route53_zone.primary.name
  rule_type   = "LOCATION"
  target_ip {
    ip        = aws_route53_resolver_endpoint.us_resolver.ip_address.ip
    port      = 53
    protocol  = "UDP"
  }
  target_ip {
    ip        = aws_route53_resolver_endpoint.eu_resolver.ip_address.ip
    port      = 53
    protocol  = "UDP"
  }
}

resource "aws_security_group" "us_resolver" {
  name        = "us-resolver-sg"
  description = "Security group for US resolver endpoint"
  vpc_id      = aws_vpc.primary.id

  ingress {
    from_port   = 53
    to_port     = 53
    protocol    = "UDP"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 53
    to_port     = 53
    protocol    = "UDP"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "eu_resolver" {
