    to_port     = 53
    protocol    = "UDP"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 53
    to_port     = 53
    protocol    = "UDP"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_vpc" "primary" {
  cidr_block = "192.0.2.0/24"
}

resource "aws_subnet" "us_subnet" {
  cidr_block = "192.0.2.0/25"
  vpc_id     = aws_vpc.primary.id
}

resource "aws_subnet" "eu_subnet" {
  cidr_block = "192.0.2.128/25"
  vpc_id     = aws_vpc.primary.id
}
