  region = "us-east-1"
}

resource "aws_dynamodb_table" "my_table" {
  name           = "my_table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "my_hash_key"
  range_key      = "my_range_key"
  read_capacity  = 1
  write_capacity = 1

  global_secondary_index {
    name            = "my_global_index"
    hash_key        = "my_global_hash_key"
    projection_type = "ALL"
    read_capacity   = 1
    write_capacity  = 1
  }

  local_secondary_index {
    name            = "my_local_index"
    projection_type = "ALL"
    range_key       = "my_local_range_key"
  }

  on_demand_throughput {
    max_read_request_units  = 1
    max_write_request_units = 1
  }

  point_in_time_recovery {
    enabled = true
  }

  replica {
    region_name = "us-west-2"
  }

  server_side_encryption {
    enabled = true
  }

  timeouts {
    create = "10m"
    delete = "10m"
    update = "10m"
  }

  ttl {
    attribute_name = "my_ttl_attribute"
    enabled        = true
  }
}
```
