  node_type = "cache.t3.micro"
  num_cache_nodes = 1
  parameter_group_name = "default.redis3.2"
  port = 6379
}

resource "aws_elasticache_user" "redis_user" {
  user_id = "redis-user"
  user_name = "redis-user"
  engine = "redis"
  access_string = "on"

  authentication_mode {
    type = "password"
    passwords = ["password123"]
  }

  depends_on = [aws_elasticache_cluster.redis_cluster]
}
```
This Terraform configuration creates an ElastiCache cluster with a Redis engine and a single node, and an ElastiCache user with a Redis engine and a password. The ElastiCache user is dependent on the ElastiCache cluster, so the cluster will be created before the user.

Note that this configuration assumes that the ElastiCache cluster and user are created in the `us-east-1` region. If you need to create them in a different region, you will need to update the `region` provider configuration accordingly.

