resource "aws_msk_connect_connector" "msk_connect_connector" {
  cluster_arn = aws_msk_cluster.msk_cluster.arn
  connector_name = "example-connector"
  connector_class = "io.debezium.connector.mysql.MySqlConnector"
  task_count = 1
  config = {
    "connector.class" = "io.debezium.connector.mysql.MySqlConnector"
    "tasks.max" = "1"
    "database.hostname" = "example-mysql-host"
    "database.port" = "3306"
    "database.user" = "example-mysql-user"
    "database.password" = "example-mysql-password"
    "database.server.id" = "184054"
    "database.server.name" = "example-mysql-server"
    "database.whitelist" = "example-mysql-database"
    "table.whitelist" = "example-mysql-table"
