provider "aws" {
  region = "us-east-1"
}

resource "aws_dynamodb_table" "my_table" {
  name = "my_table"
  billing_mode = "PROVISIONED"
  read_capacity = 5
  write_capacity = 5
  hash_key = "id"
  range_key = "name"

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "name"
    type = "S"
  }

  global_secondary_index {
    name = "name-index"
    hash_key = "name"
    projection_type = "ALL"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled = true
  }

  tags = {
    Name = "my_table"
  }
}
```
This Terraform program creates a DynamoDB table named "my_table" with a hash key of "id" and a range key of "name". It also defines a global secondary index on the "name" attribute and enables point-in-time recovery and server-side encryption. The program uses the "us-east-1" region and sets the read and write capacities to 5. The "tags" block is used to add a "Name" tag to the table.

