  Here is a complete Terraform HCL program that satisfies the requirements:
```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "codebuild_role" {
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_s3_bucket" "autograder_results" {
  bucket = "autograder-results-${random_id.result.hex}"
  acl    = "private"
}

resource "aws_codebuild_project" "autograder" {
  name          = "autograder"
  service_role  = aws_iam_role.codebuild_role.arn
  build_timeout = 60

  artifacts {
    type = "S3"
    location = aws_s3_bucket.autograder_results.arn
  }

  environment {
    compute_type    = "BUILD_GENERAL1_SMALL"
    image           = "aws/codebuild/standard:4.0"
    type            = "LINUX_CONTAINER"
    privileged_mode = true
  }

  source {
    type      = "GITHUB"
    location  = "https://github.com/<username>/<repository>"
    git_clone_depth = 1
    insecure_ssl    = false
  }

  vpc_config {
    security_group_ids = [aws_security_group.codebuild.id]
    subnets            = [aws_subnet.codebuild.id]
    vpc_id             = aws_vpc.codebuild.id
  }
}

resource "aws_security_group" "codebuild" {
  name        = "codebuild"
  description = "Allow inbound traffic from CodeBuild"
  vpc_id      = aws_vpc.codebuild.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_subnet" "codebuild" {
  cidr_block = "10.0.1.0/24"
  vpc_id     = aws_vpc.codebuild.id
}

resource "aws_vpc" "codebuild" {
  cidr_block = "10.0.0.0/16"
}

resource "random_id" "result" {
  byte_length = 4
}
```
This Terraform program creates an AWS CodeBuild project named "autograder" that runs students' code stored on GitHub in a specific environment and stores the result in an S3 bucket named "autograder-results-<random_id>". The program also creates an IAM role named "codebuild_role" that is assumed by the CodeBuild project, and a security group and subnet for the CodeBuild project to use. The program uses the `random_id` resource to generate a random ID for the S3 bucket name.

Note that this program assumes that the user has already created an AWS account and has the necessary permissions to create resources in the account. The program also assumes that the user has already created a GitHub repository with the code to be autograded.

