}

resource "aws_codebuild_project" "autograder" {
  name = "autograder"
  service_role = "arn:aws:iam::123456789012:role/service-role/codebuild-service-role"

  artifacts {
    type = "CODEPIPELINE"
  }

  build_batch_config {
    service_role = "arn:aws:iam::123456789012:role/service-role/codebuild-service-role"
  }

  cache {
    type = "S3"
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image = "aws/codebuild/standard:4.0"
    type = "LINUX_CONTAINER"
  }

  file_system_locations {
    identifier = "autograder-fs"
    location = "arn:aws:elasticfilesystem:us-east-1:123456789012:file-system/fs-0123456789abcdef0"
    mount_options = "nfsvers=4.1,rsize=1048576,wsize=1048576,hard,timeo=600,retrans=2,noresvport"
    mount_point = "/mnt/efs"
    type = "EFS"
  }

  logs_config {
    cloudwatch_logs {
      group_name = "autograder-logs"
      status = "ENABLED"
    }
  }

  secondary_artifacts {
    artifact_identifier = "autograder-results"
    type = "S3"
  }

  secondary_source_version {
    source_identifier = "autograder-source"
    source_version = "master"
  }

  secondary_sources {
    source_identifier = "autograder-source"
    type = "GITHUB"
    buildspec = "autograder-buildspec.yml"
    git_clone_depth = 1
    insecure_ssl = false
    location = "https://github.com/user/autograder.git"
    report_build_status = true
  }

  source {
    type = "GITHUB"
    buildspec = "autograder-buildspec.yml"
    git_clone_depth = 1
    insecure_ssl = false
    location = "https://github.com/user/autograder.git"
    report_build_status = true
  }

