provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "autograder_bucket" {
  bucket = "autograder-bucket-${var.environment}"
  acl    = "private"

  versioning {
    enabled = true
  }

  lifecycle_rule {
    enabled = true
    prefix  = "results/"

    expiration {
      days = 365
    }
  }

  tags = {
    Name        = "Autograder Bucket"
    Environment = var.environment
  }
}

resource "aws_codebuild_project" "autograder_project" {
  name          = "autograder-project-${var.environment}"
  service_role  = "arn:aws:iam::${var.aws_account_id}:role/service-role/codebuild-service-role"
  build_timeout = 60
  queued_timeout = 480

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type    = "BUILD_GENERAL1_SMALL"
    image           = "aws/codebuild/standard:4.0"
    type            = "LINUX_CONTAINER"
    privileged_mode = true
  }

  source {
    type      = "CODEPIPELINE"
    buildspec = "buildspec.yml"
  }

  vpc_config {
    security_group_ids = ["sg-12345678"]
    subnets            = ["subnet-12345678"]
    vpc_id             = "vpc-12345678"
  }
}

resource "aws_vpc" "autograder_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name        = "Autograder VPC"
    Environment = var.environment
  }
}

resource "aws_security_group" "autograder_sg" {
  name        = "autograder-sg-${var.environment}"
  description = "Security group for the autograder"
  vpc_id      = aws_vpc.autograder_vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name        = "Autograder SG"
    Environment = var.environment
  }
}

resource "aws_subnet" "autograder_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"

  tags = {
    Name        = "Autograder Subnet"
    Environment = var.environment
  }
}

resource "aws_route_table" "autograder_route_table" {
  vpc_id = aws_vpc.autograder_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.autograder_igw.id
  }

  tags = {
    Name        = "Autograder Route Table"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "autograder_route_table_association" {
  subnet_id      = aws_subnet.autograder_subnet.id
  route_table_id = aws_route_table.autograder_route_table.id
}

resource "aws_internet_gateway" "autograder_igw" {
  vpc_id = aws_vpc.autograder_vpc.id

  tags = {
    Name        = "Autograder IGW"
    Environment = var.environment
  }
}

resource "aws_eip" "autograder_eip" {
  vpc = true

  tags = {
    Name        = "Autograder EIP"
    Environment = var.environment
  }
}

resource "aws_nat_gateway" "autograder_nat_gateway" {
  allocation_id = aws_eip.autograder_eip.id
  subnet_id     = aws_subnet.autograder_subnet.id

