```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "autograder_bucket" {
  bucket = "autograder-bucket-${random_id.bucket_id.hex}"
  acl    = "private"

  versioning {
    enabled = true
  }

  lifecycle_rule {
    enabled = true
    prefix  = "autograder/"

    expiration {
      days = 365
    }
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

resource "aws_codebuild_project" "autograder_project" {
  name          = "autograder-project"
  service_role  = "arn:aws:iam::123456789012:role/service-role/codebuild-service-role"
  build_timeout = 60
  queued_timeout = 480

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type    = "BUILD_GENERAL1_SMALL"
    image           = "aws/codebuild/standard:4.0"
    type            = "LINUX_CONTAINER"
    privileged_mode = true
  }

  source {
    type      = "GITHUB"
    location  = "https://github.com/user/repo.git"
    buildspec = "buildspec.yml"
  }

  vpc_config {
    security_group_ids = ["sg-12345678"]
    subnets            = ["subnet-12345678"]
    vpc_id             = "vpc-12345678"
  }
}

resource "aws_vpc" "autograder_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true
  instance_tenancy     = "default"

  tags = {
    Name = "autograder-vpc"
  }
}

resource "aws_vpc_subnet" "autograder_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"

  tags = {
    Name = "autograder-subnet"
  }
}

resource "aws_security_group" "autograder_security_group" {
  name        = "autograder-security-group"
  description = "Allow inbound traffic from the VPC"
  vpc_id      = aws_vpc.autograder_vpc.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "autograder-security-group"
  }
}
```
