provider "aws" {
  region = "us-east-1"
}

resource "aws_api_gateway_rest_api" "cat_picture_api" {
  name        = "CatPictureAPI"
  description = "API for cat picture web server"
}

resource "aws_api_gateway_resource" "cat_picture_resource" {
  parent_id   = aws_api_gateway_rest_api.cat_picture_api.root_resource_id
  path_part   = "cat_pictures"
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
}

resource "aws_api_gateway_method" "cat_picture_method" {
  authorization = "NONE"
  http_method   = "GET"
  resource_id   = aws_api_gateway_resource.cat_picture_resource.id
  rest_api_id   = aws_api_gateway_rest_api.cat_picture_api.id
}

resource "aws_api_gateway_integration" "cat_picture_integration" {
  http_method = aws_api_gateway_method.cat_picture_method.http_method
  resource_id = aws_api_gateway_resource.cat_picture_resource.id
  rest_api_id = aws_api_gateway_rest_api.cat_picture_api.id
  type        = "AWS_PROXY"

  uri = "arn:aws:apigateway:${var.region}:lambda:path/2015-03-31/functions/arn:aws:lambda:${var.region}:${var.account_id}:function:${var.function_name}/invocations"
}

resource "aws_s3_bucket" "cat_picture_bucket" {
  bucket = "cat-picture-bucket-${var.region}"
  acl    = "private"

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3000
  }

  lifecycle_rule {
    enabled = true
    prefix  = "cat_pictures/"

    expiration {
      days = 365
    }
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

resource "aws_s3_bucket_object" "cat_picture_object" {
  bucket = aws_s3_bucket.cat_picture_bucket.id
  key    = "cat_pictures/${var.function_name}.jpg"
  source = "cat_pictures/${var.function_name}.jpg"
  etag   = filemd5("cat_pictures/${var.function_name}.jpg")
}

resource "aws_lambda_function" "cat_picture_function" {
  function_name = var.function_name
  role          = aws_iam_role.cat_picture_role.arn
  handler       = "index.handler"
  runtime       = "nodejs12.x"
  timeout       = 30

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_picture_bucket.id
    }
  }
}

resource "aws_iam_role" "cat_picture_role" {
  name = "cat_picture_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      },
    ]
  })
}

resource "aws_iam_role_policy" "cat_picture_policy" {
  name = "cat_picture_policy"
  role = aws_iam_role.cat_picture_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
        ]
        Effect   = "Allow"
        Resource = aws_s3_bucket.cat_picture_bucket.arn
      },
    ]
  })
}
