}

resource "aws_eventbridge_event_target" "daily_event_target" {
  name        = "daily_event_target"
  description = "Invoke the Lambda function when the event rule is triggered"
  rule        = aws_eventbridge_event_rule.daily_event_rule.name
  arn         = aws_lambda_function.daily_lambda.arn
}

resource "aws_lambda_function" "daily_lambda" {
  function_name = "daily_lambda"
  role          = aws_iam_role.daily_lambda_role.arn
  handler       = "index.handler"
  runtime       = "nodejs14.x"
  memory_size   = 128
  timeout       = 30

  environment {
