provider "aws" {
  region = "us-east-1"
}

resource "aws_lb" "video_streaming_lb" {
  name               = "video-streaming-lb"
  load_balancer_type = "application"
  subnets            = ["subnet-12345678", "subnet-87654321"]
  security_groups    = ["sg-12345678"]
}

resource "aws_lb_target_group" "video_streaming_target_group" {
  name     = "video-streaming-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = "vpc-12345678"
}

resource "aws_route53_zone" "video_streaming_zone" {
  name = "video-streaming.com"
}

resource "aws_route53_record" "video_streaming_record" {
  name    = "video-streaming.com"
  type    = "A"
  zone_id = aws_route53_zone.video_streaming_zone.zone_id
  alias {
    evaluate_target_health = true
    name                   = aws_lb.video_streaming_lb.dns_name
    zone_id                = aws_lb.video_streaming_lb.zone_id
  }
}

resource "aws_vpc" "video_streaming_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true
}

resource "aws_vpc_subnet" "video_streaming_subnet" {
  vpc_id     = aws_vpc.video_streaming_vpc.id
  cidr_block = "10.0.1.0/24"
}

resource "aws_vpc_security_group" "video_streaming_security_group" {
  vpc_id = aws_vpc.video_streaming_vpc.id
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_ec2_instance" "video_streaming_instance" {
  ami           = "ami-12345678"
  instance_type = "t3.micro"
  subnet_id     = aws_vpc_subnet.video_streaming_subnet.id
  vpc_security_group_ids = [aws_vpc_security_group.video_streaming_security_group.id]
}
```
This Terraform configuration creates a video streaming site with multiple servers to balance load. The load balancer distributes traffic to the target group, which contains the EC2 instance. The Route53 record points to the Route53 zone, which contains the load balancer. The VPC contains the subnet and security group for the EC2 instance.

Note that this configuration assumes that the user has already created the necessary AWS resources, such as the VPC, subnet, security group, and EC2 instance, and that the user has provided the necessary values for the `aws_lb`, `aws_lb_target_group`, `aws_route53_zone`, and `aws_route53_record` resources. If the user does not have these resources, they can be created in Terraform using the `aws_vpc`, `aws_vpc_subnet`, `aws_vpc_security_group`, and `aws_ec2_instance` resources.

