resource "aws_s3_bucket" "bucket" {
  bucket = "my-bucket"
  acl    = "private"

  cors_rule {
    allowed_methods = ["GET", "PUT", "POST"]
    allowed_origins = ["*"]
  }

  grant {
    permissions = ["FULL_CONTROL"]
    type        = "Group"
    uri         = "http://acs.amazonaws.com/groups/global/AllUsers"
  }

  lifecycle_rule {
