  Here is a complete Terraform HCL program that satisfies the requirements:
```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_lb" "my_lb" {
  name               = "my-lb"
  internal           = false
  load_balancer_type = "application"
  subnets            = ["subnet-12345678", "subnet-87654321"]

  access_logs {
    bucket = "my-lb-logs"
    prefix = "my-lb-logs"
  }

  connection_logs {
    bucket = "my-lb-logs"
    prefix = "my-lb-logs"
  }

  ipam_pools {
    ipv4_ipam_pool_id = "ipam-pool-12345678"
  }

  minimum_load_balancer_capacity {
    capacity_units = 2
  }

  subnet_mapping {
    subnet_id = "subnet-12345678"
    allocation_id = "eipalloc-12345678"
    private_ipv4_address = "10.0.1.100"
  }

  timeouts {
    create = "10m"
    update = "10m"
  }
}

resource "aws_lb_listener" "my_listener" {
  load_balancer_arn = aws_lb.my_lb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "redirect"
    target_group_arn = aws_lb_target_group.my_target_group.arn
  }

  mutual_authentication {
    mode = "OPTIONAL"
  }

  timeouts {
    create = "10m"
    update = "10m"
  }
}

resource "aws_lb_target_group" "my_target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = "vpc-12345678"

  health_check {
    enabled = true
    interval = 30
    path = "/"
    port = 80
    protocol = "HTTP"
    timeout = 5
    healthy_threshold = 2
    unhealthy_threshold = 2
  }
}
```
This Terraform program creates an AWS Load Balancer with a Listener and a Target Group. The Listener has a default action of redirecting to the Target Group. The Target Group has a health check configured.

Note that this program assumes that the AWS provider is configured with the correct region and credentials. If you are using a different region or credentials, you will need to modify the provider block accordingly.

